// Local html2canvas placeholder for development.
// GitHub Actions replaces this file with the real html2canvas.min.js from npm before building the APK.
(function () {
  if (window.html2canvas) return;
  var cdn = document.createElement('script');
  cdn.src = 'https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js';
  cdn.async = false;
  cdn.onerror = function () {
    console.warn('html2canvas belum tersedia. Build APK GitHub Actions akan memasukkan file lokal otomatis.');
  };
  document.head.appendChild(cdn);
})();
